-- 0003: drizzle-kit baseline — NO-OP.
--
-- Migrations 0000-0002 were hand-written and already applied to every
-- environment via `wrangler d1 migrations apply`. This file marks the point
-- where the drizzle-kit snapshot chain (migrations/meta/) was baselined to
-- exactly that applied schema, so every future migration is generated by:
--     bun run db:generate        # drizzle-kit generate (diff vs meta snapshot)
--     bun run db:migrate:local   # wrangler d1 migrations apply DB --local
--     bun run db:migrate:remote  # wrangler d1 migrations apply DB --remote
-- Never let drizzle-kit itself apply D1 migrations; wrangler owns application.
SELECT 1;
